import ftplib
import logging

from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class FtpControl(object):
    """Library to control FTP connections"""
    # pylint: disable=broad-except

    def __init__(self, ftp_ip, ftp_user, ftp_pass):
        """

        :param ftp_ip:
        :param ftp_user:
        :param ftp_pass:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UTILS'})
        self.ftp_ip = ftp_ip
        self.ftp_user = ftp_user
        self.ftp_pass = ftp_pass
        self.ftp_conn = None

    def __del__(self):
        if hasattr(self, 'ftp_conn'):
            self.ftp_conn.quit()

    def login_to_ftp(self):
        """Establish connection to FTP server"""
        try:
            self.logger.info('Connecting to the FTP server {}'.format(self.ftp_ip))
            self.ftp_conn = ftplib.FTP(self.ftp_ip)
            self.ftp_conn.login(self.ftp_user, self.ftp_pass)
        except Exception as e:
            self.logger.exception('Some error occured during establishing connection to FTP: {}'.format(str(e)))
        else:
            self.logger.info('Connection established.')

    def upload_file(self, filename):
        """Upload a file to FTP server"""
        self.ftp_conn.storbinary('STOR ' + filename, open(filename, 'rb'))

    def get_file(self, remote_filepath, local_filepath):
        """Get file from FTP server"""
        try:
            self.logger.info('Downloading file {}.'.format(remote_filepath))
            local_filepath = open(local_filepath, 'wb')
            self.ftp_conn.retrbinary('RETR ' + remote_filepath, local_filepath.write, 1024)
            local_filepath.close()
        except Exception as e:
            self.logger.exception('Some error occured: {}'.format(str(e)))
        else:
            self.logger.info('File downloaded.')

    def check_if_file_exists(self, filepath):
        """Check if file exists on FTP server"""
        try:
            self.ftp_conn.size(filepath)
        except Exception:
            return 0
        else:
            self.logger.info('File on FTP found!')
            return 1

    def remove_file(self, filepath):
        """Remove a file from FTP server"""
        try:
            self.ftp_conn.delete(filepath)
        except Exception:
            return 0
        else:
            self.logger.info('File {} deleted.!'.format(filepath))
            return 1


if __name__ == "__main__":
    ftp = FtpControl('10.45.169.134', 'root', 'siemens')
    ftp.login_to_ftp()
    ftp.check_if_file_exists('/resources/adb.zip')
